import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours annuel de 3e orienté vers les compétences du BEPC.
class TroisiemeCompletionScreen extends StatelessWidget {
  const TroisiemeCompletionScreen({super.key});
  static const _units = <_Unit>[
    _Unit('T1 • Français','Compréhension, narration et point de vue','Pour étudier un texte au BEPC, lire d’abord le titre et la consigne, puis faire une lecture globale et une lecture précise. Identifier le thème, la situation initiale, les événements, les personnages, le cadre spatio-temporel et le point de vue. Distinguer narrateur interne (il participe aux faits) et externe (il raconte de l’extérieur). Justifier chaque réponse par un indice du texte. Pour résumer, sélectionner les idées essentielles, respecter leur ordre logique, reformuler sans copier et ne pas ajouter d’opinion.','Un résumé reprend les événements principaux dans un texte plus court.','Quel élément doit être conservé dans un résumé ?',['Les idées essentielles','Tous les détails secondaires','Des événements inventés'],0,'Un résumé restitue fidèlement les idées principales.'),
    _Unit('T1 • Mathématiques','Calcul numérique, racines et puissances','Pour calculer une expression, traiter les parenthèses, les puissances et racines, puis multiplications et divisions de gauche à droite, enfin additions et soustractions. Réduire les fractions lorsque c’est possible et vérifier le résultat par une estimation. Pour a positif, √a désigne le nombre positif dont le carré vaut a. Une puissance représente une multiplication répétée ; avec une même base, aᵐ × aⁿ = aᵐ⁺ⁿ.','√49 = 7 et 2³ × 2² = 2⁵ = 32.','Calcule √121.',['10','11','12'],1,'11 × 11 = 121, donc √121 = 11.'),
    _Unit('T1 • Anglais','Reading comprehension and present perfect','En compréhension écrite, repérer le titre, le thème, les personnages, les dates et les connecteurs ; répondre avec des éléments précis du texte. Le present perfect se forme avec have/has + participe passé. Il exprime notamment une expérience ou un fait passé ayant un lien avec le présent. Distinguer : I visited Lomé yesterday (date passée terminée) et I have visited Lomé (expérience).','I have already finished my homework.','Choose the correct sentence.',['She have seen the film.','She has seen the film.','She has saw the film.'],1,'À la troisième personne du singulier, on utilise has + participe passé.'),
    _Unit('T1 • SVT','Génétique et transmission des caractères','L'information génétique est portée par l'ADN organisé en chromosomes dans le noyau de la plupart des cellules. Les gènes sont des portions d'ADN qui participent à la détermination de caractères. À la reproduction, les descendants reçoivent une partie de l'information génétique de chaque parent. Un caractère observable peut dépendre des gènes et du milieu (alimentation, climat, habitudes). Ne pas confondre caractère héréditaire et caractère acquis.','Les ressemblances familiales peuvent être liées à la transmission de gènes.','Où se trouve l’essentiel de l’information génétique dans une cellule humaine ?',['Dans les chromosomes du noyau','Dans les cheveux uniquement','Dans le sang seulement'],0,'Les chromosomes du noyau portent l’essentiel de l’information génétique.'),
    _Unit('T1 • Physique-Chimie','Structure de la matière et réactions chimiques','Un atome est constitué d'un noyau contenant protons et neutrons, entouré d'électrons. Les atomes s'associent pour former des molécules. Une transformation physique change l'état ou l'aspect sans créer une nouvelle espèce chimique ; une réaction chimique forme de nouvelles espèces. Au cours d'une réaction, les atomes sont conservés et se réarrangent. Pour équilibrer une équation, ajuster les coefficients sans modifier les formules.','Lors de la formation de l’eau, les atomes d’hydrogène et d’oxygène se réorganisent.','Au cours d’une réaction chimique ordinaire, que deviennent les atomes ?',['Ils disparaissent tous','Ils sont réorganisés','Ils deviennent de la lumière'],1,'Les atomes se conservent et se réarrangent pour former de nouvelles espèces.'),
    _Unit('T1 • Histoire-Géographie-EMC','Colonisation, indépendances et citoyenneté','Pour étudier la colonisation, distinguer conquête, administration, exploitation économique, transformations sociales et résistances des populations. Les indépendances africaines résultent de mobilisations politiques, syndicales, populaires et de négociations, selon des trajectoires propres à chaque territoire. En analyse documentaire, préciser nature, auteur, date, destinataire et contexte, puis confronter le document aux connaissances. En EMC, relier droits, devoirs, règles communes et participation citoyenne.','Pour analyser un document historique, identifier sa date, son auteur, sa nature et son contexte.','Quel élément aide à situer un document historique ?',['Sa date et son contexte','Sa couleur uniquement','Le nombre de lettres du titre'],0,'La date et le contexte permettent de comprendre le document.'),
    _Unit('T2 • Français','Argumentation, grammaire et discours','Construire un paragraphe argumentatif en quatre étapes : annoncer la thèse, présenter un argument, l'expliquer, puis l'illustrer par un exemple précis. Utiliser des connecteurs adaptés : d'abord, ensuite, en effet, cependant, donc, enfin. Le discours direct reproduit les paroles avec guillemets ; le discours indirect les intègre dans une proposition et peut entraîner des changements de pronoms, de repères temporels et de temps verbaux. Relire les accords et la ponctuation.','Thèse : lire est utile ; argument : la lecture enrichit le vocabulaire ; exemple : elle fait découvrir de nouveaux mots.','Quel connecteur exprime une conséquence ?',['Cependant','Donc','D’abord'],1,'Donc introduit une conséquence ou une conclusion.'),
    _Unit('T2 • Mathématiques','Équations, inéquations et fonctions','Pour résoudre ax+b=c, effectuer la même opération aux deux membres afin d'isoler x, puis vérifier en remplaçant x dans l'équation initiale. Pour une inéquation, conserver le sens lors d'une addition ou multiplication par un nombre positif ; inverser le signe si l'on multiplie ou divise par un nombre négatif. Pour une fonction, calculer une image en remplaçant x par sa valeur et lire un antécédent à partir de l'image donnée.','5x − 4 = 16 donne 5x = 20 puis x = 4.','Résous 3x + 2 = 17.',['x = 3','x = 5','x = 7'],1,'3x = 15, donc x = 5.'),
    _Unit('T2 • Anglais','Passive voice and expressing opinions','La voix passive se construit avec le verbe be au temps nécessaire suivi du participe passé. Le complément d'agent introduit par by peut être ajouté si l'information est utile. Pour exprimer un avis, annoncer clairement son point de vue, donner une raison avec because et nuancer avec however ou although. Dans un texte, repérer les pronoms, les temps et les connecteurs pour comprendre l'enchaînement des idées.','English is spoken in many countries.','Choose the passive form of « People build houses ».',['Houses are built.','Houses build.','Houses is building.'],0,'Le sujet houses reçoit l’action : are + built.'),
    _Unit('T2 • SVT','Reproduction, santé et prévention','Les appareils reproducteurs produisent les gamètes : spermatozoïdes et ovules. La fécondation est leur fusion et conduit à la cellule-œuf, qui se divise au début du développement embryonnaire. La puberté s'accompagne de changements physiques et émotionnels variables selon les personnes. La santé repose sur l'information scientifique, l'hygiène, le respect du consentement, la prévention des infections et le recours à des professionnels de santé.','La cellule-œuf se forme lors de la fécondation.','Comment appelle-t-on la rencontre des gamètes ?',['Fécondation','Photosynthèse','Digestion'],0,'La fécondation est l’union des cellules reproductrices.'),
    _Unit('T2 • Physique-Chimie','Électricité : loi d’Ohm et puissance','La loi d'Ohm relie tension U, résistance R et intensité I : U=RI. La puissance électrique vaut P=UI et l'énergie consommée peut se calculer par E=Pt lorsque les unités sont cohérentes. Le voltmètre se branche en dérivation et l'ampèremètre en série. Avant tout calcul, écrire les données, convertir les unités, choisir la formule, remplacer les symboles puis indiquer l'unité. Ne jamais manipuler une installation sous tension.','Si R = 10 Ω et I = 0,2 A, alors U = 2 V.','Une résistance de 5 Ω est traversée par 2 A. Quelle tension mesure-t-on ?',['2,5 V','7 V','10 V'],2,'U = R × I = 5 × 2 = 10 V.'),
    _Unit('T2 • Histoire-Géographie-EMC','Développement, ressources et population','Distinguer croissance économique et développement humain. Étudier plusieurs indicateurs : revenu, scolarisation, accès aux soins, espérance de vie, eau potable et emploi. La croissance démographique dépend des naissances, des décès et des migrations. Pour analyser une carte, lire le titre, l'échelle, l'orientation, la légende et la source ; décrire ensuite les contrastes spatiaux et proposer des explications prudentes. Relier les enjeux aux réalités du Togo et de l'Afrique de l'Ouest.','Une légende permet d’interpréter les couleurs et symboles d’une carte.','Quel indicateur renseigne directement sur la santé d’une population ?',['Espérance de vie','Longueur d’une route','Nombre de drapeaux'],0,'L’espérance de vie est un indicateur démographique et sanitaire.'),
    _Unit('T3 • Français','Synthèse, lettre et préparation au BEPC','Pour une synthèse, comprendre chaque document, relever les idées communes et les différences, regrouper les informations par thèmes et rédiger avec ses propres mots. Une lettre formelle comporte lieu et date si demandés, destinataire, objet, formule d'appel, paragraphes organisés, formule de politesse et signature. Au BEPC, gérer le temps : lire toutes les consignes, commencer par les questions maîtrisées, présenter les calculs et réserver quelques minutes à la relecture.','Une lettre officielle indique clairement l’objet et adopte un ton respectueux.','Quel élément est indispensable dans une lettre formelle ?',['Un objet clair','Des abréviations familières','Des émoticônes obligatoires'],0,'L’objet annonce précisément le motif de la lettre.'),
    _Unit('T3 • Mathématiques','Thalès, trigonométrie et statistiques','Avant d'appliquer Thalès, vérifier l'alignement des points et le parallélisme, écrire les rapports dans le même ordre, puis calculer la longueur inconnue. Dans un triangle rectangle, sin(angle)=opposé/hypoténuse, cos(angle)=adjacent/hypoténuse et tan(angle)=opposé/adjacent ; choisir le rapport qui contient les données connues. En statistiques, distinguer effectif, fréquence, moyenne et médiane, et vérifier que le résultat est cohérent avec la série.','Dans un triangle rectangle, sin(angle) = côté opposé / hypoténuse.','La moyenne de 8, 10 et 12 vaut…',['9','10','11'],1,'(8 + 10 + 12) ÷ 3 = 30 ÷ 3 = 10.'),
    _Unit('T3 • Anglais','Reported speech and exam communication','Au discours rapporté, adapter les pronoms et les expressions de temps et de lieu au nouveau contexte. Après un verbe introducteur au passé, les temps peuvent reculer : present simple vers past simple, present continuous vers past continuous, will vers would. Pour rédiger une réponse d'examen, reprendre le mot-clé de la question, construire une phrase complète et vérifier sujet-verbe, temps et orthographe.','Direct: He said, “I am tired.” Reported: He said that he was tired.','Which verb introduces reported speech in the example?',['said','because','tomorrow'],0,'Said introduit les paroles rapportées.'),
    _Unit('T3 • SVT','Immunité, microbes et équilibre écologique','Les micro-organismes comprennent notamment bactéries, champignons microscopiques et virus ; tous ne provoquent pas des maladies. La peau et les muqueuses forment des barrières naturelles. L'immunité mobilise des défenses de l'organisme ; la vaccination prépare une réponse immunitaire spécifique. Respecter les règles d'hygiène, les conseils médicaux et les mesures de prévention. Dans un écosystème, producteurs, consommateurs et décomposeurs sont liés par des relations alimentaires.','Le lavage des mains réduit la transmission de nombreux microbes.','Quel geste limite la transmission de microbes ?',['Se laver les mains','Partager une serviette sale','Boire de l’eau non traitée'],0,'Le lavage des mains est une mesure d’hygiène efficace.'),
    _Unit('T3 • Physique-Chimie','Mécanique, énergie et révisions expérimentales','La vitesse moyenne se calcule par v=d/t ; convertir les unités avant le calcul. Une force est une action mécanique caractérisée par un point d'application, une direction, un sens et une intensité. Elle peut accélérer, ralentir, dévier ou déformer un objet. L'énergie peut être cinétique, potentielle, thermique, chimique ou électrique et se transforme. Un compte rendu scientifique sépare observations, résultats, interprétation et conclusion.','Un véhicule parcourt 100 km en 2 h : sa vitesse moyenne est 50 km/h.','Une distance de 150 km est parcourue en 3 h. Quelle est la vitesse moyenne ?',['30 km/h','50 km/h','450 km/h'],1,'v = d/t = 150/3 = 50 km/h.'),
    _Unit('T3 • Histoire-Géographie-EMC','Institutions, paix et préparation à la vie citoyenne','Identifier les principales institutions de la République et leurs fonctions sans confondre les pouvoirs exécutif, législatif et judiciaire. Les services publics répondent à des besoins collectifs. La citoyenneté implique respect des lois, droits fondamentaux, devoirs, participation et solidarité. Face à un conflit, privilégier dialogue, médiation et recours aux règles communes. Pour réussir l'épreuve, définir les notions, organiser les idées et illustrer par un exemple pertinent.','Débattre consiste à écouter, argumenter et respecter les opinions différentes.','Quel comportement favorise un débat démocratique ?',['Écouter et argumenter sans violence','Empêcher les autres de parler','Insulter les opposants'],0,'Le débat démocratique repose sur l’écoute et le respect.'),
  ];
  static int get unitCount => _units.length;
  static int get lessonCount => _units.length;
  static List<Exercise> assessmentExercisesForTerm(int term, {String? subjectName}) {
    final result = <Exercise>[];
    for (var i = 0; i < _units.length; i++) {
      final unit = _units[i];
      if (!unit.title.startsWith('T$term •')) continue;
      if (subjectName != null && !_matches(unit.title, subjectName)) continue;
      result.add(Exercise(id: 'three_t${term}_u${i}', lessonId: 'three_t${term}_u${i}', question: unit.question, options: unit.options, correctIndex: unit.answer, explanation: unit.explanation));
    }
    return result;
  }
  static bool _matches(String title, String subject) {
    final t = title.toLowerCase(), s = subject.toLowerCase();
    if (s.contains('français') || s.contains('francais')) return t.contains('français');
    if (s.contains('math')) return t.contains('mathématiques');
    if (s.contains('anglais') || s.contains('english')) return t.contains('anglais');
    if (s.contains('svt') || s.contains('science')) return t.contains('svt');
    if (s.contains('physique') || s.contains('chimie') || s.contains('technologie')) return t.contains('physique-chimie');
    if (s.contains('histoire') || s.contains('géographie') || s.contains('education') || s.contains('éducation') || s.contains('emc')) return t.contains('histoire-géographie-emc');
    return false;
  }
  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Complément 3ème • Année complète • BEPC')),
    body: ListView(padding: const EdgeInsets.all(16), children: [
      Card(child: Padding(padding: const EdgeInsets.all(16), child: Text('${unitCount} unités • ${lessonCount} leçons • 3 trimestres\nCours, exemples, questions corrigées et préparation progressive au BEPC.', style: const TextStyle(fontWeight: FontWeight.w600)))),
      for (final unit in _units) _UnitTile(unit: unit),
    ]),
  );
}
class _Unit {
  final String title, objective, content, example, question;
  final List<String> options;
  final int answer;
  final String explanation;
  const _Unit(this.title, this.objective, this.content, this.example, this.question, this.options, this.answer, this.explanation);
}
class _UnitTile extends StatefulWidget {
  final _Unit unit;
  const _UnitTile({required this.unit});
  @override State<_UnitTile> createState() => _UnitTileState();
}
class _UnitTileState extends State<_UnitTile> {
  int? choice;
  bool checked = false;
  @override Widget build(BuildContext context) {
    final unit = widget.unit;
    return Card(margin: const EdgeInsets.only(bottom: 10), child: ExpansionTile(
      title: Text(unit.title, style: const TextStyle(fontWeight: FontWeight.bold)),
      subtitle: Text(unit.objective),
      children: [Padding(padding: const EdgeInsets.fromLTRB(16, 0, 16, 16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(unit.content), const SizedBox(height: 8),
        Text('Exemple : ${unit.example}', style: const TextStyle(fontStyle: FontStyle.italic)),
        const SizedBox(height: 12), Text(unit.question, style: const TextStyle(fontWeight: FontWeight.bold)),
        for (var i = 0; i < unit.options.length; i++) RadioListTile<int>(dense: true, contentPadding: EdgeInsets.zero, value: i, groupValue: choice, title: Text(unit.options[i]), onChanged: checked ? null : (value) => setState(() => choice = value)),
        FilledButton.tonal(onPressed: choice == null ? null : () => setState(() => checked = true), child: const Text('Vérifier ma réponse')),
        if (checked) Text('${choice == unit.answer ? 'Bonne réponse ! ' : 'À revoir. Bonne réponse : ${unit.options[unit.answer]}. '}${unit.explanation}', style: TextStyle(fontWeight: FontWeight.w600, color: choice == unit.answer ? Colors.green.shade800 : Theme.of(context).colorScheme.error)),
        if (checked) TextButton(onPressed: () => setState(() { choice = null; checked = false; }), child: const Text('Recommencer')),
      ]))],
    ));
  }
}
